    rewrite (gso_1RB1LC_1LA1RD_0RB1LA_0LC0RB p j E).
    exact (srun_sound tm true true chb_1RB1LC_1LA1RD_0RB1LA_0LC0RB B0_1RB1LC_1LA1RD_0RB1LA_0LC0RB BB1_1RB1LC_1LA1RD_0RB1LA_0LC0RB 4 7
             run_boot_1RB1LC_1LA1RD_0RB1LA_0LC0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 10), (cden [] [] j B1_1RB1LC_1LA1RD_0RB1LA_0LC0RB).
