    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LC_1LA1RD_0RC1LA_0LC0RB B0_1RB1LC_1LA1RD_0RC1LA_0LC0RB B1_1RB1LC_1LA1RD_0RC1LA_0LC0RB 4 15 p j' [] []).
    + exact run_ovf_1RB1LC_1LA1RD_0RC1LA_0LC0RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LC_1LA1RD_0RC1LA_0LC0RB p j' E).
    + exact (geo_1RB1LC_1LA1RD_0RC1LA_0LC0RB p j' E).
    + lia.
Qed.

