Lemma fireo_1RB1LC_1LA1RD_0RC1LA_0LC0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LC_1LA1RD_0RC1LA_0LC0RB = Some t ->
  forall p j, cview p = (S j, None) ->
