(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LC_1LA1RD_0RC1RD_1RA0LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_000_010_01 q0 ++ [S0]) [] j A0_1RB1LC_1LA1RD_0RC1RD_1RA0LA.
Proof.
  intros p j q0 E. destruct (Alph_000_010_01.cview_some_Alph_000_010_01 p j q0 E) as (H1 & _).
  unfold Cc_1RB1LC_1LA1RD_0RC1RD_1RA0LA, cden, A0_1RB1LC_1LA1RD_0RC1RD_1RA0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S0;S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
