  split; [lia|]. split; [| exact (gei_1RB1LC_1LA1RD_0RC1RD_1RA0LA p j q0 E)].
  rewrite (gsi_1RB1LC_1LA1RD_0RC1RD_1RA0LA p j q0 E).
  exact (srun_sound tm false true chi_1RB1LC_1LA1RD_0RC1RD_1RA0LA A0_1RB1LC_1LA1RD_0RC1RD_1RA0LA A1_1RB1LC_1LA1RD_0RC1RD_1RA0LA 12 12
           run_int_1RB1LC_1LA1RD_0RC1RD_1RA0LA (Ap_Alph_000_010_01 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
