Lemma geo_1RB1LC_1LA1RD_0RC1RD_1RA0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LC_1LA1RD_0RC1RD_1RA0LA) = lift (Cc (Pos.succ p)).
