  - destruct (lapi_1RB1LC_1LA1RD_0RD0LA_0LD1RB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LC_1LA1RD_0RD0LA_0LD1RB B0_1RB1LC_1LA1RD_0RD0LA_0LD1RB B1_1RB1LC_1LA1RD_0RD0LA_0LD1RB 4 15 p j' [] []).
    + exact run_ovf_1RB1LC_1LA1RD_0RD0LA_0LD1RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LC_1LA1RD_0RD0LA_0LD1RB p j' E).
    + exact (geo_1RB1LC_1LA1RD_0RD0LA_0LD1RB p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LC_1LA1RD_0RD0LA_0LD1RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 12.
  assert (H : match csteps tm 12 c0 with
