    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LC_1LB1LC_0RD0LA_1LA1RD [SCycL 2 0; SWin 6; SCycR 2; SWin 1; SWinR 2] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LC_1LB1LC_0RD0LA_1LA1RD [SCycL 2 0; SWin 6; SCycR 2; SWin 1; SWinR 3] (StB, S1) ltac:(vm_compute; reflexivity)
