(** ** The lap *)

Lemma lap_1RB1LC_1LC0LC_1RD1LB_1LA0RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
