    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LC_1LC0LC_1RD1LB_1LA0RD B0_1RB1LC_1LC0LC_1RD1LB_1LA0RD B1_1RB1LC_1LC0LC_1RD1LB_1LA0RD 4 12 p j' [] []).
    + exact run_ovf_1RB1LC_1LC0LC_1RD1LB_1LA0RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LC_1LC0LC_1RD1LB_1LA0RD p j' E).
    + exact (geo_1RB1LC_1LC0LC_1RD1LB_1LA0RD p j' E).
    + lia.
Qed.

