    [exact Hst | discriminate | reflexivity | exact (gsi_1RB1LC_1LC0LC_1RD1LB_1LA0RD p j q0 E)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LC_1LC0LC_1RD1LB_1LA0RD : forall t, ~ In t pins_1RB1LC_1LC0LC_1RD1LB_1LA0RD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LC_1LC0LC_1RD1LB_1LA0RD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LC_1LC0LC_1RD1LB_1LA0RD
      with (l := []).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LC_1LC0LC_1RD1LB_1LA0RD
      with (l := [SWin 2; SCycL 2 0; SWin 4]).
    vm_compute; reflexivity.
  - (* B0: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB1LC_1LC0LC_1RD1LB_1LA0RD (StB, S0)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB1LC_1LC0LC_1RD1LB_1LA0RD [SWin 2; SCycL 2 0; SWin 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LC_1LC0LC_1RD1LB_1LA0RD
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LC_1LC0LC_1RD1LB_1LA0RD
      with (l := [SWin 2; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LC_1LC0LC_1RD1LB_1LA0RD
      with (l := [SWin 2]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1LC_1LC0LC_1RD1LB_1LA0RD
      with (l := [SWin 2; SCycL 2 0; SWin 3]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1LC_1LC0LC_1RD1LB_1LA0RD
      with (l := [SWin 2; SCycL 2 0; SWin 4; SWinL 2]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB1LC_1LC0LC_1RD1LB_1LA0RD : NeverQuasiHaltsTr tm_1RB1LC_1LC0LC_1RD1LB_1LA0RD.
Proof.
  apply (glue_neverqhtr tm_1RB1LC_1LC0LC_1RD1LB_1LA0RD pins_1RB1LC_1LC0LC_1RD1LB_1LA0RD Cc 2).
