Lemma gen_1RB1LC_1LC1RD_0RB1LA_0LC0RB : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_1RB1LC_1LC1RD_0RB1LA_0LC0RB) = lift (Cin (Pos.succ v)).
