    exists (0 * 0 + 4), (cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] 0 Z1_1RB1LC_1RC0RB_0LD1LB_1LA0LA).
    split; [lia|]. split; [| exact HB].
