(** ** The lap *)

Lemma lap_1RB1LC_1RC0RB_0LD1LB_1LA0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
