  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LC_1RC0RB_0LD1LB_1LA0LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LC_1RC0RB_0LD1LB_1LA0LA B0_1RB1LC_1RC0RB_0LD1LB_1LA0LA B1_1RB1LC_1RC0RB_0LD1LB_1LA0LA 8 12 p j' [] []).
    + exact run_ovf_1RB1LC_1RC0RB_0LD1LB_1LA0LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LC_1RC0RB_0LD1LB_1LA0LA p j' E).
    + exact (geo_1RB1LC_1RC0RB_0LD1LB_1LA0LA p j' E).
    + lia.
