  - destruct (lapi_1RB1LC_1RC0RB_1LD0LC_1LA1RC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LC_1RC0RB_1LD0LC_1LA1RC B0_1RB1LC_1RC0RB_1LD0LC_1LA1RC B1_1RB1LC_1RC0RB_1LD0LC_1LA1RC 6 16 p j' [] []).
    + exact run_ovf_1RB1LC_1RC0RB_1LD0LC_1LA1RC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LC_1RC0RB_1LD0LC_1LA1RC p j' E).
    + exact (geo_1RB1LC_1RC0RB_1LD0LC_1LA1RC p j' E).
    + lia.
