(** ** The lap *)

Lemma lap_1RB1LC_1RC1LA_1LB0RD_0LA1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
