  - destruct (lapi_1RB1LC_1RC1LA_1LB0RD_0LA1RD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LC_1RC1LA_1LB0RD_0LA1RD B0_1RB1LC_1RC1LA_1LB0RD_0LA1RD B1_1RB1LC_1RC1LA_1LB0RD_0LA1RD 6 14 p j' [] []).
    + exact run_ovf_1RB1LC_1RC1LA_1LB0RD_0LA1RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LC_1RC1LA_1LB0RD_0LA1RD p j' E).
    + exact (geo_1RB1LC_1RC1LA_1LB0RD_0LA1RD p j' E).
    + lia.
Qed.

