  - destruct (lapi_1RB1LD_0LB1RC_1LD0RB_1RB1LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LD_0LB1RC_1LD0RB_1RB1LA B0_1RB1LD_0LB1RC_1LD0RB_1RB1LA B1_1RB1LD_0LB1RC_1LD0RB_1RB1LA 4 7 p j' [] []).
    + exact run_ovf_1RB1LD_0LB1RC_1LD0RB_1RB1LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LD_0LB1RC_1LD0RB_1RB1LA p j' E).
    + exact (geo_1RB1LD_0LB1RC_1LD0RB_1RB1LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LD_0LB1RC_1LD0RB_1RB1LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
