      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LD_0LC0RB_1LA0LD_1LC1RC (StC, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LD_0LC0RB_1LA0LD_1LC1RC [SRotL 1; SWin 1; SCycL 3 0; SWin 3] (StC, S1) ltac:(vm_compute; reflexivity)
