  assert (HD : cden [] [] j B1_1RB1LD_0LC0RB_1LA1LC_1LA1RC
             = (StA, (rep [S0;S0] (S j) ++ [S1], S0, ([S1]) ++ [S0]))).
  { unfold cden, B1_1RB1LD_0LC0RB_1LA1LC_1LA1RC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
