(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LD_0LC0RB_1LA1LC_1LC0RC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin3 lapin3_1RB1LD_0LC0RB_1LA1LC_1LC0RC p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (6 * j + 10), (cden [] [] j BB1_1RB1LD_0LC0RB_1LA1LC_1LC0RC).
      split; [lia|]. split; [| exact (gbo_1RB1LD_0LC0RB_1LA1LC_1LC0RC j)].
      rewrite (gso_1RB1LD_0LC0RB_1LA1LC_1LC0RC p j E).
      exact (srun_sound tm true true chb_1RB1LD_0LC0RB_1LA1LC_1LC0RC B0_1RB1LD_0LC0RB_1LA1LC_1LC0RC BB1_1RB1LD_0LC0RB_1LA1LC_1LC0RC 6 10
               run_boot_1RB1LD_0LC0RB_1LA1LC_1LC0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1LD_0LC0RB_1LA1LC_1LC0RC p (pow2 j) (pow2 j));
        [exact HB1|].
      exists (6 * j + 4), (cden [] [] j BM1_1RB1LD_0LC0RB_1LA1LC_1LC0RC).
      split; [| exact (gbo2_1RB1LD_0LC0RB_1LA1LC_1LC0RC j)].
      rewrite (gxi_1RB1LD_0LC0RB_1LA1LC_1LC0RC j).
      exact (srun_sound tm true true chm_1RB1LD_0LC0RB_1LA1LC_1LC0RC BM0_1RB1LD_0LC0RB_1LA1LC_1LC0RC BM1_1RB1LD_0LC0RB_1LA1LC_1LC0RC 6 4
               run_shift_1RB1LD_0LC0RB_1LA1LC_1LC0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB3 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin3 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin2 Cin3 lapin2_1RB1LD_0LC0RB_1LA1LC_1LC0RC p (pow2 j) (pow2 j));
        [exact HB2|].
      exists (6 * j + 14), (cden [] [] j BM31_1RB1LD_0LC0RB_1LA1LC_1LC0RC).
      split; [| exact (gbo3_1RB1LD_0LC0RB_1LA1LC_1LC0RC j)].
      rewrite (gxi2_1RB1LD_0LC0RB_1LA1LC_1LC0RC j).
      exact (srun_sound tm true true chm3_1RB1LD_0LC0RB_1LA1LC_1LC0RC BM30_1RB1LD_0LC0RB_1LA1LC_1LC0RC BM31_1RB1LD_0LC0RB_1LA1LC_1LC0RC 6 14
               run_shift3_1RB1LD_0LC0RB_1LA1LC_1LC0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    exact HB3.
  - exists (6 * j + 12), (cden [] [] j B1_1RB1LD_0LC0RB_1LA1LC_1LC0RC).
    split; [| exact (geo_1RB1LD_0LC0RB_1LA1LC_1LC0RC p j E)].
    rewrite (gxi3_1RB1LD_0LC0RB_1LA1LC_1LC0RC j).
    exact (srun_sound tm true true che_1RB1LD_0LC0RB_1LA1LC_1LC0RC BE0_1RB1LD_0LC0RB_1LA1LC_1LC0RC B1_1RB1LD_0LC0RB_1LA1LC_1LC0RC 6 12
             run_exit_1RB1LD_0LC0RB_1LA1LC_1LC0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
