      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB1LD_0LC0RB_1LA1LC_1LC0RC : NeverQuasiHaltsTr tm_1RB1LD_0LC0RB_1LA1LC_1LC0RC.
Proof.
  apply (glue_neverqhtr tm_1RB1LD_0LC0RB_1LA1LC_1LC0RC pins_1RB1LD_0LC0RB_1LA1LC_1LC0RC Cc 1).
