    intros p1 j1 E1.
    exact (firex_1RB1LD_0LC0RB_1LA1LC_1LC1LA [SRotL 1; SWin 1; SCycL 3 0; SWin 3] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LD_0LC0RB_1LA1LC_1LC1LA [SWin 1; SWinR 3; SCycL 3 0; SWin 4; SCycR 3; SWin 2; SUnrotL 2; SRotL 1; SWin 1; SRotL 1; SWin 5; SRotL 1; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
