      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 5]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LD_0LC0RB_1LA1LC_1RC0RC
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 1]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LD_0LC0RB_1LA1LC_1RC0RC
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LD_0LC0RB_1LA1LC_1RC0RC
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 6]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LD_0LC0RB_1LA1LC_1RC0RC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LD_0LC0RB_1LA1LC_1RC0RC
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 3]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1LD_0LC0RB_1LA1LC_1RC0RC
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 8; SCycR 3; SWin 1; SUnrotL 1; SRotL 1; SWin 1; SRotL 1; SWin 5; SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D1 *)
