      exact (srun_sound tm true true chm_1RB1LD_0LC0RB_1LA1LC_1RC1LA BM0_1RB1LD_0LC0RB_1LA1LC_1RC1LA BM1_1RB1LD_0LC0RB_1LA1LC_1RC1LA 8 4
               run_shift_1RB1LD_0LC0RB_1LA1LC_1RC1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB3 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin3 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin2 Cin3 lapin2_1RB1LD_0LC0RB_1LA1LC_1RC1LA p (pow2 j) (pow2 j));
        [exact HB2|].
